// Install Service Worker and cache core assets
// Install Service Worker and cache core assets
self.addEventListener("install", (event) => {
  self.skipWaiting()

  event.waitUntil(
    caches.open("cache").then((cache) => {
      return Promise.all(
        ASSETS.map((url) => {
          return cache.add(url).catch((err) => {
            console.error("❌ Failed to cache asset:", url, err)
          })
        }),
      )
    }),
  )
})

// Activate the worker, claim clients, and enable Navigation Preload
self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // Enable navigation preload if supported
      if (self.registration.navigationPreload) {
        await self.registration.navigationPreload.enable()
      }
      // Take control of the page immediately
      await clients.claim()
    })(),
  )
})
let failedToFetch = false
// Network-first strategy: always prefer the live server,
// only serve from cache if the network request fails
self.addEventListener("fetch", (event) => {
  if (event.request.method !== "GET") return
  if (failedToFetch)
    return event.respondWith(
      caches.match(event.request, { ignoreSearch: true }),
    )

  event.respondWith(
    (async () => {
      // 1. FAST PATH FOR PAGE RELOADS:
      // If this is a page navigation (HTML request), check for preloaded response first
      if (event.request.mode === "navigate") {
        const preloadResponse = await event.preloadResponse
        if (preloadResponse) return preloadResponse
      }

      // 2. Standard Network-First Strategy
      try {
        const networkResponse = await fetch(event.request)

        if (
          String(event.request.url).startsWith("http://127.0.0.1")
        ) {
          const cloned = networkResponse.clone()
          event.waitUntil(
            caches
              .open("cache")
              .then((cache) => cache.put(event.request, cloned)),
          )
        }
        return networkResponse
      } catch (err) {
        // Fallback to cache if network fails (e.g. server is off)
        const cachedResponse = await caches.match(event.request, {
          ignoreSearch: true,
        })
        if (cachedResponse) return cachedResponse
        throw err
      }
    })(),
  )
})
